const cnFiles={"lib/machine-programs.ts":"import {db} from './data';\nexport const programSchema=`CREATE TABLE IF NOT EXISTS machine_cn_programs(id TEXT PRIMARY KEY,machine_id TEXT NOT NULL REFERENCES machines(id) ON DELETE CASCADE,number TEXT NOT NULL COLLATE NOCASE,name TEXT NOT NULL,UNIQUE(machine_id,number))`;\nlet ready:Promise<unknown>|undefined;\nexport async function ensurePrograms(){if(!ready)ready=db().prepare(programSchema).run().catch(e=>{ready=undefined;throw e});await ready;}\n","app/api/machine-programs/route.ts":"import {isAdmin} from '@/lib/auth';\nimport {classId} from '@/lib/classes';\nimport {db,jsonError} from '@/lib/data';\nimport {ensurePrograms} from '@/lib/machine-programs';\nexport const dynamic='force-dynamic';\nconst text=(v:unknown)=>typeof v==='string'?v.trim():'';\nexport async function GET(request:Request){\n if(!await isAdmin()&&!await classId())return jsonError('Connecte-toi pour consulter les programmes.',401);\n const machineId=new URL(request.url).searchParams.get('machineId');if(!machineId||machineId.length>80)return jsonError('Machine requise.');\n if(!await db().prepare('SELECT id FROM machines WHERE id=?').bind(machineId).first())return jsonError('Machine inconnue.',404);\n await ensurePrograms();const programs=(await db().prepare('SELECT id,number,name FROM machine_cn_programs WHERE machine_id=? ORDER BY number COLLATE NOCASE,name').bind(machineId).all()).results;\n return Response.json({programs},{headers:{'Cache-Control':'private, no-store'}});\n}\nexport async function POST(request:Request){\n if(!await isAdmin())return jsonError('Accès réservé aux administrateurs.',403);\n const origin=request.headers.get('origin');if(origin&&origin!==new URL(request.url).origin)return jsonError('Origine refusée.',403);\n let b:Record<string,unknown>;try{b=await request.json()}catch{return jsonError('Données invalides.')}\n const machineId=text(b.machineId),number=text(b.number).toUpperCase(),name=text(b.name),id=text(b.id);\n if(!machineId||machineId.length>80||id.length>80||!number||number.length>40||!name||name.length>160||/[\\x00-\\x1f]/.test(number+name))return jsonError('Saisis un numéro (40 caractères maximum) et un nom (160 maximum).');\n if(!await db().prepare('SELECT id FROM machines WHERE id=?').bind(machineId).first())return jsonError('Machine inconnue.',404);\n await ensurePrograms();\n try{\n  if(id){const r=await db().prepare('UPDATE machine_cn_programs SET number=?,name=? WHERE id=? AND machine_id=?').bind(number,name,id,machineId).run();if(!r.meta.changes)return jsonError('Programme introuvable.',404);return Response.json({id});}\n  const key=crypto.randomUUID();await db().prepare('INSERT INTO machine_cn_programs(id,machine_id,number,name) VALUES (?,?,?,?)').bind(key,machineId,number,name).run();return Response.json({id:key});\n }catch(e){if(String(e).includes('UNIQUE constraint'))return jsonError('Ce numéro existe déjà sur cette machine.',409);throw e;}\n}\nexport async function DELETE(request:Request){\n if(!await isAdmin())return jsonError('Accès réservé aux administrateurs.',403);\n const origin=request.headers.get('origin');if(origin&&origin!==new URL(request.url).origin)return jsonError('Origine refusée.',403);\n const url=new URL(request.url),id=url.searchParams.get('id'),machineId=url.searchParams.get('machineId');if(!id||!machineId)return jsonError('Programme et machine requis.');\n await ensurePrograms();const result=await db().prepare('DELETE FROM machine_cn_programs WHERE id=? AND machine_id=?').bind(id,machineId).run();return result.meta.changes?Response.json({ok:true}):jsonError('Programme introuvable.',404);\n}\n","app/machine-programs.tsx":"'use client';\nimport {useCallback,useEffect,useState} from 'react';\nimport {CirclePlus,Pencil,Trash2} from 'lucide-react';\nimport {toast} from 'sonner';\nimport './machine-programs.css';\ntype Program={id:string;number:string;name:string};\nconst auth=():Record<string,string>=>{const token=sessionStorage.getItem('atelier_admin_token')||sessionStorage.getItem('atelier_student_token');return token?{Authorization:`Bearer ${token}`}:{}};\nexport default function MachinePrograms({machineId,admin}:{machineId:string;admin:boolean}){\n const [programs,setPrograms]=useState<Program[]>([]),[loading,setLoading]=useState(true),[error,setError]=useState(''),[busy,setBusy]=useState(false),[editing,setEditing]=useState<Program|null|undefined>(undefined),[number,setNumber]=useState(''),[name,setName]=useState('');\n const load=useCallback(async(signal?:AbortSignal)=>{setError('');try{const r=await fetch('/api/machine-programs?machineId='+encodeURIComponent(machineId),{headers:auth(),cache:'no-store',signal});const v=await r.json();if(!r.ok)throw Error(v.error||'Liste indisponible.');if(!signal?.aborted)setPrograms(v.programs);}catch(e){if(!signal?.aborted)setError(e instanceof Error?e.message:'Liste indisponible.')}finally{if(!signal?.aborted)setLoading(false)}},[machineId]);\n useEffect(()=>{const controller=new AbortController();setLoading(true);setPrograms([]);setEditing(undefined);load(controller.signal);return()=>controller.abort()},[load]);\n function edit(p?:Program){setEditing(p||null);setNumber(p?.number||'');setName(p?.name||'')}\n async function save(e:React.FormEvent){e.preventDefault();setBusy(true);try{const r=await fetch('/api/machine-programs',{method:'POST',headers:{...auth(),'Content-Type':'application/json'},body:JSON.stringify({machineId,id:editing?.id,number,name})});const v=await r.json();if(!r.ok)throw Error(v.error||'Enregistrement impossible.');setEditing(undefined);toast.success('Programme enregistré.');await load()}catch(e){toast.error(e instanceof Error?e.message:'Enregistrement impossible.')}finally{setBusy(false)}}\n async function remove(p:Program){if(!window.confirm(`Supprimer le programme ${p.number} — ${p.name} ?`))return;setBusy(true);try{const r=await fetch('/api/machine-programs?machineId='+encodeURIComponent(machineId)+'&id='+encodeURIComponent(p.id),{method:'DELETE',headers:auth()});const v=await r.json();if(!r.ok)throw Error(v.error||'Suppression impossible.');if(editing?.id===p.id)setEditing(undefined);toast.success('Programme supprimé.');await load()}catch(e){toast.error(e instanceof Error?e.message:'Suppression impossible.')}finally{setBusy(false)}}\n return <section className=\"cn-programs\" aria-label=\"Liste des programmes CN\"><div className=\"cn-heading\"><h3>Répertoire des programmes</h3>{admin&&<button className=\"secondary\" disabled={busy} onClick={()=>edit()}><CirclePlus size={16}/> Ajouter un programme</button>}</div>\n {admin&&editing!==undefined&&<form className=\"cn-form\" onSubmit={save}><label>Numéro de programme<input required autoFocus maxLength={40} placeholder=\"Ex. O01234\" value={number} onChange={e=>setNumber(e.target.value)} disabled={busy}/></label><label>Nom du programme<input required maxLength={160} placeholder=\"Ex. Axe Stirling — finition\" value={name} onChange={e=>setName(e.target.value)} disabled={busy}/></label><div><button className=\"primary\" disabled={busy}>{busy?'Enregistrement…':editing?'Enregistrer':'Ajouter'}</button><button type=\"button\" className=\"secondary\" disabled={busy} onClick={()=>setEditing(undefined)}>Annuler</button></div></form>}\n {error?<p role=\"alert\">{error} <button className=\"text-action\" onClick={()=>load()}>Réessayer</button></p>:loading?<p role=\"status\">Chargement des programmes…</p>:programs.length?<div className=\"cn-list\">{programs.map(p=><div className=\"cn-row\" key={p.id}><strong>{p.number}</strong><span>{p.name}</span>{admin&&<div><button className=\"icon-plain\" disabled={busy} onClick={()=>edit(p)} aria-label={'Modifier le programme '+p.number}><Pencil size={16}/></button><button className=\"icon-plain\" disabled={busy} onClick={()=>remove(p)} aria-label={'Supprimer le programme '+p.number}><Trash2 size={16}/></button></div>}</div>)}</div>:<p>Aucun programme enregistré pour cette machine.</p>}\n </section>;\n}\n","app/machine-programs.css":".cn-programs{border-bottom:1px solid #40566b;padding-bottom:20px;margin-bottom:20px}.cn-heading{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap}.cn-heading h3{font-size:16px;margin:0}.cn-heading button{display:flex;align-items:center;gap:8px}.cn-form{display:grid;gap:12px;margin:16px 0;padding:16px;border:1px solid #40566b;border-radius:10px}.cn-form label{display:grid;gap:6px;font-size:13px}.cn-form input{width:100%;min-width:0;box-sizing:border-box;border:1px solid #40566b;border-radius:8px;background:#101b27;color:#e1edf8;padding:11px}.cn-form>div{display:flex;gap:10px;flex-wrap:wrap}.cn-list{display:grid;gap:8px;margin-top:16px}.cn-row{display:flex;align-items:center;gap:12px;padding:12px;border:1px solid #40566b;border-radius:8px;flex-wrap:wrap;overflow-wrap:anywhere}.cn-row>strong{color:#86c5ff;min-width:80px}.cn-row>span{flex:1;min-width:100px}.cn-row>div{display:flex;gap:8px}.cn-programs>p{font-size:13px;color:#b7c9db}:root[data-theme=\"light\"] .cn-form input{background:white;color:#18344d;border-color:#afc5d8}:root[data-theme=\"light\"] .cn-row>strong{color:#165f9a}:root[data-theme=\"light\"] .cn-programs>p{color:#455f78}:root[data-theme=\"light\"] .cn-row,:root[data-theme=\"light\"] .cn-form,:root[data-theme=\"light\"] .cn-programs{border-color:#c6d7e5}\n"};
for(const [relative,contents] of Object.entries(cnFiles)){
 const target=path.join(root,relative);let check=root;for(const segment of relative.split('/')){check=path.join(check,segment);if(fs.existsSync(check)&&fs.lstatSync(check).isSymbolicLink())fail('Lien symbolique refusé : '+relative);}
 fs.mkdirSync(path.dirname(target),{recursive:true});fs.writeFileSync(target,contents);
}
